"""Editorial content for CC-12, Civil Code arts. 1,606-1,720 (revoked 1,620-1,629 excluded)."""
def row(says, means, example, warning, term, definition):
    return {"target": None, "o_que_diz": says, "o_que_significa": means, "exemplo_pratico": example, "atencao": warning, "palavras_dificeis": [{"termo": term, "explicacao": definition}]}

ROWS = {
    "1606": row("A ação destinada a provar a filiação pertence ao filho enquanto vivo; herdeiros assumem a pretensão se ele morrer menor ou incapaz e podem continuar processo já iniciado.", "O estado de filiação é direito personalíssimo, mas a lei permite sucessão processual nas hipóteses expressamente indicadas.", "Filho incapaz falece antes de ajuizar a demanda, e seus herdeiros buscam a declaração do vínculo parental.", "Herdeiros não recebem autorização geral: a transmissão e o prosseguimento dependem das situações descritas no artigo.", "Sucessão processual", "substituição da parte falecida por quem pode continuar o processo"),
    "1607": row("Pais podem reconhecer, juntos ou separadamente, filho nascido fora do casamento.", "A declaração de um genitor não depende de reconhecimento simultâneo pelo outro.", "A mãe registra a maternidade e, meses depois, o pai formaliza separadamente a paternidade.", "Toda filiação tem igual dignidade; a expressão legal sobre origem matrimonial não cria categoria inferior de filho.", "Reconhecimento", "ato jurídico que declara vínculo de filiação"),
    "1608": row("Se a maternidade estiver no registro de nascimento, a mãe só poderá contestá-la demonstrando falsidade do registro ou das declarações nele lançadas.", "O assento registral tem força probatória e não é afastado por simples arrependimento ou alegação sem prova.", "Pessoa indicada como mãe prova que a declaração usada no registro era falsa.", "A controvérsia exige prova da falsidade e deve considerar identidade, origem biológica e vínculos juridicamente protegidos.", "Assento registral", "registro oficial do nascimento e da filiação"),
    "1609": row("O reconhecimento irrevogável pode ocorrer no registro, por escritura ou escrito arquivado, por testamento ou por declaração expressa ao juiz; pode anteceder o nascimento ou ocorrer após a morte se houver descendentes.", "A lei oferece formas solenes alternativas para declarar a filiação, inclusive em ato cujo objeto principal seja outro.", "Pai reconhece o filho por escritura pública antes do nascimento.", "A forma deve ser comprovável e a hipótese posterior à morte exige que o filho tenha deixado descendentes.", "Escritura pública", "documento lavrado por tabelião com fé pública"),
    "1610": row("O reconhecimento de filho é irrevogável, inclusive quando inserido em testamento.", "Revogar o testamento não desfaz a declaração de filiação nele validamente realizada.", "Testador altera suas disposições patrimoniais, mas não pode retirar o reconhecimento do filho.", "Irrevogabilidade não impede ação fundada em falsidade, erro relevante ou outro vício juridicamente demonstrado.", "Irrevogável", "ato que não pode ser desfeito por simples vontade de quem o praticou"),
    "1611": row("O Código condiciona a residência, no lar conjugal, do filho reconhecido por apenas um cônjuge ao consentimento do outro.", "A regra literal protege a organização doméstica, mas sua aplicação deve priorizar igualdade entre filhos, convivência familiar e melhor interesse da criança.", "Cônjuge reconhece filho menor e a família define sua residência considerando proteção e convivência.", "O dispositivo não autoriza discriminação por origem da filiação nem afasta deveres parentais e proteção integral.", "Lar conjugal", "residência comum organizada pelos cônjuges"),
    "1612": row("O menor reconhecido fica, em princípio, com o genitor que o reconheceu; havendo reconhecimento por ambos e desacordo, decide-se conforme seu melhor interesse.", "Guarda não é prêmio ao genitor: a solução deve proteger segurança, cuidado, vínculos e desenvolvimento do filho.", "Ambos reconhecem a criança e discordam da guarda; o juiz avalia qual arranjo melhor a protege.", "A regra convive com a disciplina atual da guarda compartilhada e sempre se subordina ao melhor interesse do menor.", "Melhor interesse", "critério que prioriza os direitos e necessidades da criança ou adolescente"),
    "1613": row("Condição ou termo acrescentado ao reconhecimento de filho não produz efeito.", "A filiação não pode depender de evento futuro nem ser limitada por prazo escolhido pelo declarante.", "Pai declara que só reconhecerá o filho se ele adotar certo sobrenome; a condição é ineficaz.", "A ineficácia alcança a restrição indevida, sem converter a filiação em vínculo negociável.", "Termo", "evento futuro e certo usado para marcar início ou fim de efeitos"),
    "1614": row("Pessoa maior precisa consentir para ser reconhecida; o menor pode impugnar o reconhecimento nos quatro anos posteriores à maioridade ou emancipação.", "O artigo protege autonomia do adulto e prevê prazo específico para oposição daquele reconhecido quando menor.", "Jovem reconhecido na infância impugna o ato dentro do período contado de sua maioridade.", "A filiação envolve direito à identidade; prazos e cabimento de outras ações devem ser examinados conforme Constituição e jurisprudência aplicável.", "Impugnação", "contestação jurídica da validade ou eficácia de um ato"),
    "1615": row("Pessoa com interesse juridicamente justificável pode contestar ação investigatória de paternidade ou maternidade.", "A intervenção exige interesse concreto na definição do estado de filiação, não mera curiosidade.", "Herdeiro demonstra impacto sucessório direto e apresenta defesa na investigação.", "O justo interesse deve ser demonstrado, preservando intimidade, dignidade e prioridade do direito à filiação.", "Justo interesse", "vínculo jurídico relevante que legitima participação na causa"),
    "1616": row("Sentença favorável na investigação gera efeitos equivalentes ao reconhecimento e pode determinar criação e educação fora da companhia de um ou de ambos os pais.", "A declaração estabelece filiação, mas convivência e guarda são definidas conforme proteção concreta do filho.", "Paternidade é declarada, porém o juiz mantém a criança em ambiente protetivo diante de risco comprovado.", "Afastamento da companhia parental não decorre automaticamente da resistência à investigação; exige fundamento protetivo.", "Sentença constitutiva", "decisão que estabelece uma situação jurídica com efeitos próprios"),
    "1617": row("O vínculo paterno ou materno pode decorrer de casamento posteriormente declarado nulo, mesmo sem requisitos do casamento putativo.", "A invalidade matrimonial não prejudica a filiação nem reduz direitos do filho.", "Casamento dos pais é anulado, mas a filiação e seus efeitos permanecem.", "A igualdade constitucional entre filhos impede qualquer diminuição por situação conjugal dos pais.", "Casamento putativo", "casamento inválido que pode produzir efeitos para quem agiu de boa-fé"),
    "1618": row("A adoção de crianças e adolescentes segue o Estatuto da Criança e do Adolescente.", "O Código remete requisitos, procedimento, consentimentos, estágio de convivência e controles à legislação especial.", "Pretendentes habilitados seguem o procedimento judicial disciplinado pelo ECA.", "Não se devem reconstruir regras de adoção apenas pelo Código Civil; prevalece a disciplina especial vigente e o melhor interesse.", "Legislação especial", "lei que regula de modo específico determinada matéria"),
    "1619": row("A adoção de pessoa maior de dezoito anos exige atuação efetiva do poder público e sentença, aplicando-se o ECA quando compatível.", "Mesmo entre adultos, a adoção não nasce de simples contrato particular e depende de controle judicial.", "Pessoa adulta e seu vínculo socioafetivo são examinados em processo que termina com sentença constitutiva.", "A aplicação do ECA é adaptada à maioridade; consentimento, finalidade legítima e efeitos familiares continuam relevantes.", "Assistência efetiva", "participação real do poder público na formação e controle do ato"),

    "1630": row("Filhos permanecem sujeitos ao poder familiar enquanto menores.", "Pais exercem deveres e poderes de proteção, criação e representação até a maioridade ou outra causa legal de extinção.", "Pais administram questões civis do filho de quinze anos dentro dos limites legais.", "Poder familiar é função protetiva em benefício do filho, não domínio sobre sua pessoa ou direitos.", "Poder familiar", "conjunto de deveres e responsabilidades parentais relativos ao filho menor"),
    "1631": row("Durante casamento ou união estável, ambos os pais exercem o poder familiar; impedimento de um concentra o exercício no outro, e divergência pode ser resolvida judicialmente.", "A responsabilidade parental é igual e não se subordina ao gênero ou à situação patrimonial dos pais.", "Pais discordam sobre decisão escolar relevante e pedem solução ao juiz.", "O recurso judicial deve priorizar o interesse do filho e não transforma um dos pais em titular superior.", "Exercício exclusivo", "atuação por um só genitor quando o outro está ausente ou impedido"),
    "1632": row("Separação, divórcio ou fim da união estável não altera os deveres parentais, salvo a organização da companhia física dos filhos.", "O encerramento da relação conjugal não encerra poder familiar, cuidado, sustento ou participação na educação.", "Após o divórcio, ambos continuam decidindo temas relevantes do filho, embora ele resida principalmente com um deles.", "Convivência e guarda seguem disciplina própria e o melhor interesse, sem confundir conjugalidade com parentalidade.", "Parentalidade", "relação jurídica de responsabilidades entre pais e filhos"),
    "1633": row("Sem reconhecimento paterno, o poder familiar é exercido pela mãe; se ela for desconhecida ou incapaz, o menor recebe tutor.", "A falta de um vínculo parental estabelecido não deixa a criança sem representação e proteção jurídica.", "Mãe incapaz de exercer os deveres parentais e pai não reconhecido levam à nomeação de tutor.", "Reconhecimento posterior ou definição judicial da filiação pode modificar a estrutura de representação.", "Tutor", "pessoa nomeada para proteger e representar menor sem poder familiar exercível"),
    "1634": row("Ambos os pais exercem plenamente o poder familiar, independentemente da situação conjugal, abrangendo criação, educação, guarda, consentimentos, representação, assistência e proteção.", "O artigo reúne responsabilidades parentais que devem ser desempenhadas conjuntamente e em benefício dos filhos.", "Pais separados autorizam viagem internacional e acompanham conjuntamente educação e saúde do filho.", "Obediência e serviços compatíveis com idade não autorizam violência, exploração ou violação de direitos fundamentais.", "Assistência civil", "complementação da vontade do adolescente nos atos em que a lei a exige"),
    "1635": row("O poder familiar termina por morte, emancipação, maioridade, adoção ou decisão judicial nos casos legais.", "A enumeração identifica fatos e decisões que encerram a autoridade parental.", "Ao atingir dezoito anos, o filho deixa de estar sujeito ao poder familiar.", "A adoção transfere vínculos parentais conforme o regime legal; decisão de perda exige processo e fundamento específico.", "Extinção", "encerramento definitivo de uma relação ou poder jurídico"),
    "1636": row("Novo casamento ou união estável do pai ou da mãe não retira direitos e deveres parentais relativos aos filhos anteriores, nem autoriza interferência automática do novo parceiro.", "A recomposição familiar preserva o poder familiar do genitor e a autonomia parental.", "Mãe casa novamente e continua exercendo integralmente responsabilidades sobre filho de relação anterior.", "O novo cônjuge pode formar vínculo familiar relevante, mas não assume nem elimina poder familiar apenas pela união.", "Família recomposta", "núcleo familiar formado por nova união com filhos de relações anteriores"),
    "1637": row("Abuso de autoridade, descumprimento de deveres ou ruína dos bens do filho permite ao juiz adotar medidas protetivas, inclusive suspensão; condenação criminal na hipótese legal também pode suspendê-lo.", "A suspensão protege pessoa e patrimônio do menor e deve ser proporcional ao risco comprovado.", "Genitor dilapida patrimônio do filho e tem o exercício parental suspenso judicialmente.", "A suspensão depende de decisão e contraditório; normas posteriores devem ser consideradas na hipótese criminal.", "Suspensão", "interrupção temporária do exercício do poder familiar"),
    "1638": row("Perda judicial do poder familiar pode decorrer de castigo excessivo, abandono, faltas graves reiteradas, entrega irregular para adoção e crimes graves especificados contra outro titular ou descendente.", "A sanção extrema exige processo, prova e enquadramento legal, sempre orientados pela proteção do filho.", "Genitor pratica violência grave abrangida pela lei e o juiz decreta a perda após o devido processo.", "Perda não é automática por acusação e não afasta eventual responsabilidade civil ou penal; deve prevalecer proteção integral.", "Perda do poder familiar", "retirada judicial definitiva das atribuições parentais"),

    "1639": row("Antes do casamento, nubentes podem escolher disciplina patrimonial; ela vigora desde a celebração e só muda depois por decisão judicial motivada de ambos, preservando terceiros.", "A autonomia patrimonial existe, mas alteração posterior exige controle para evitar fraude ou prejuízo.", "Casal pede mudança de regime e demonstra motivo legítimo, sem afetar credores.", "A decisão produz efeitos conforme o caso e não pode apagar direitos de terceiros já constituídos.", "Regime de bens", "conjunto de regras sobre patrimônio dos cônjuges"),
    "1640": row("Sem pacto válido, aplica-se comunhão parcial; a opção por esse regime pode constar da habilitação, enquanto outras escolhas exigem escritura pública antenupcial.", "A comunhão parcial funciona como regime legal supletivo.", "Casal não celebra pacto e passa a seguir comunhão parcial desde o casamento.", "A forma do pacto é requisito de validade e escolhas patrimoniais devem preceder a celebração.", "Regime supletivo", "regra aplicada quando as partes não escolhem validamente outra"),
    "1641": row("O texto impõe separação de bens diante de causa suspensiva, idade superior a setenta anos ou casamento dependente de suprimento judicial.", "Nessas situações, a lei restringe a escolha patrimonial dos nubentes.", "Pessoa com mais de setenta anos casa sob o regime indicado no artigo.", "A aplicação contemporânea, especialmente do critério etário, deve observar a interpretação constitucional e vinculante vigente e a autonomia protegida.", "Separação obrigatória", "regime patrimonial imposto por hipótese legal"),
    "1642": row("Qualquer cônjuge pode administrar bens próprios, exercer profissão e defender patrimônio contra atos praticados sem consentimento, além dos demais atos não proibidos.", "O artigo assegura autonomia civil e instrumentos de reação a negócios patrimoniais irregulares do outro.", "Cônjuge busca invalidar aval prestado sem outorga quando ela era legalmente necessária.", "Cada medida tem requisitos próprios e algumas referências literais devem ser lidas com igualdade entre cônjuges e legislação atual.", "Direito regressivo", "pretensão de recuperar de responsável valor suportado perante terceiro"),
    "1643": row("Cônjuges podem, sem autorização recíproca, adquirir itens necessários à vida doméstica e tomar empréstimo para essa finalidade.", "A gestão ordinária do lar pode ser realizada por qualquer deles.", "Um cônjuge compra eletrodoméstico essencial a crédito sem pedir autorização ao outro.", "A independência alcança necessidades domésticas razoáveis, não qualquer dívida pessoal apresentada como familiar.", "Economia doméstica", "conjunto de necessidades materiais ordinárias do lar"),
    "1644": row("Dívidas assumidas para necessidades domésticas previstas no artigo anterior obrigam solidariamente ambos os cônjuges.", "O credor pode cobrar de qualquer um, desde que a obrigação realmente atenda à economia do lar.", "Empréstimo usado para despesa essencial da casa pode ser exigido de ambos.", "A solidariedade depende da finalidade legal da dívida e não se presume para gastos estranhos à família.", "Solidariedade", "responsabilidade que permite cobrar a dívida integral de qualquer obrigado"),
    "1645": row("Ações patrimoniais indicadas nos incisos III, IV e V do art. 1.642 pertencem ao cônjuge prejudicado e a seus herdeiros.", "A legitimidade para reagir ao ato irregular permanece com quem sofreu o prejuízo e pode transmitir-se sucessoriamente.", "Após falecimento, herdeiros prosseguem na pretensão de recuperar imóvel alienado sem outorga.", "É necessário identificar a hipótese exata do art. 1.642 e demonstrar prejuízo e legitimidade.", "Legitimidade ativa", "autorização jurídica para propor determinada ação"),
    "1646": row("Terceiro prejudicado pela invalidação favorável ao cônjuge pode cobrar regressivamente de quem praticou o negócio irregular ou de seus herdeiros.", "A proteção conjugal não deixa sem remédio o terceiro que confiou no negócio e depois sofreu perda.", "Fiador obtém anulação por falta de outorga e o credor busca ressarcimento de quem contratou irregularmente.", "O regresso não restaura o ato inválido e depende do dano e da responsabilidade de quem o praticou.", "Ação regressiva", "cobrança contra quem deve suportar definitivamente o prejuízo"),
    "1647": row("Fora da separação absoluta, alienar ou onerar imóvel, litigar sobre ele, prestar fiança ou aval e realizar certas doações exige autorização do outro cônjuge.", "A outorga protege patrimônio e meação contra decisões unilaterais relevantes.", "Proprietário casado em comunhão parcial precisa da outorga para hipotecar imóvel.", "Regime, natureza do bem e tipo de ato devem ser conferidos; exceções e legislação especial podem afastar a exigência.", "Outorga conjugal", "consentimento do outro cônjuge para ato patrimonial relevante"),
    "1648": row("O juiz pode suprir a outorga quando ela é recusada sem motivo justo ou não pode ser concedida.", "O controle judicial evita que impedimento ou recusa abusiva paralise negócio legítimo.", "Cônjuge impossibilitado de manifestar vontade leva o outro a pedir suprimento para venda necessária.", "O suprimento não é automático: exige demonstrar necessidade e ausência de razão legítima para negar.", "Suprimento judicial", "decisão que substitui consentimento exigido pela lei"),
    "1649": row("Ato feito sem outorga necessária e sem suprimento é anulável; o cônjuge pode pedir anulação até dois anos após o fim da sociedade conjugal, e ratificação formal pode validá-lo.", "O negócio produz efeitos até ser invalidado e pode ser confirmado na forma legal.", "Fiança sem outorga é questionada pelo cônjuge dentro do prazo legal.", "O prazo, a forma de aprovação e o regime de bens devem ser verificados; anulabilidade não equivale a nulidade automática.", "Anulável", "ato eficaz até ser desfeito por iniciativa legitimada"),
    "1650": row("Somente o cônjuge que deveria consentir, ou seus herdeiros, pode pedir invalidação por falta de outorga ou suprimento.", "A lei restringe a legitimidade para proteger interesse conjugal específico.", "Terceiro sem vínculo não pode usar a falta de outorga para propor a ação reservada ao cônjuge.", "Outras defesas próprias do terceiro não são eliminadas, mas esta invalidação tem legitimados determinados.", "Legitimado", "pessoa autorizada pela lei a exercer uma pretensão"),
    "1651": row("Se um cônjuge não puder administrar os bens sob sua responsabilidade, o outro gere bens comuns e do consorte, podendo alienar móveis comuns e, com autorização judicial, outros bens indicados.", "A substituição assegura continuidade da administração, com controle reforçado para alienações relevantes.", "Cônjuge incapacitado temporariamente é substituído na gestão, e venda de imóvel recebe autorização judicial.", "A atuação deve preservar interesse do consorte e respeitar regime de bens, limites legais e prestação de contas.", "Administração substitutiva", "gestão assumida por outro quando o titular está impedido"),
    "1652": row("Quem possui bens particulares do outro cônjuge responde como usufrutuário, mandatário ou depositário, conforme renda comum, mandato ou simples guarda.", "A natureza concreta da posse define deveres, frutos, diligência e restituição.", "Cônjuge administra bem particular com autorização tácita e responde pelas regras do mandato.", "A classificação depende dos fatos; posse conjugal não transforma automaticamente bem particular em comum.", "Depositário", "quem guarda bem alheio com dever de conservação e restituição"),

    "1653": row("Pacto antenupcial precisa de escritura pública para ser válido e só produz eficácia se o casamento ocorrer.", "Documento particular não substitui a forma solene, e pacto sem casamento não rege patrimônio conjugal.", "Casal assina contrato privado de regime; a escolha não vale como pacto antenupcial.", "Invalidade da forma e ineficácia por falta de casamento são consequências distintas.", "Pacto antenupcial", "convenção anterior ao casamento que escolhe ou adapta regime de bens"),
    "1654": row("Pacto feito por menor depende da aprovação do representante legal, salvo quando incide separação obrigatória.", "A assistência completa a capacidade para a escolha patrimonial nas hipóteses permitidas.", "Nubente menor celebra pacto com aprovação expressa de seu representante.", "A autorização para casar não substitui automaticamente os requisitos específicos do pacto.", "Representante legal", "pessoa autorizada a atuar ou consentir em nome de incapaz"),
    "1655": row("É nula cláusula antenupcial que contrarie regra legal inderrogável.", "Autonomia do casal não permite afastar norma de ordem pública.", "Pacto tenta eliminar dever legal indisponível e a cláusula é inválida.", "A nulidade pode atingir apenas a disposição incompatível, conforme separabilidade e conteúdo do pacto.", "Norma cogente", "regra obrigatória que não pode ser afastada por acordo"),
    "1656": row("No regime de participação final nos aquestos, o pacto pode permitir livre alienação de imóveis particulares.", "A convenção antecipa autorização para que cada cônjuge disponha de imóvel exclusivamente seu.", "Pacto autoriza venda individual de apartamento particular durante o casamento.", "A liberdade não alcança bem comum nem afasta proteção de terceiros ou requisitos registrais.", "Aquestos", "bens adquiridos onerosamente durante o casamento considerados na partilha"),
    "1657": row("Convenção antenupcial só pode ser oposta a terceiros após registro especial no Registro de Imóveis do domicílio conjugal.", "Entre os cônjuges o pacto pode valer, mas publicidade registral é necessária para atingir terceiros.", "Credor só fica sujeito ao regime convencional depois do registro exigido.", "Escritura e registro cumprem funções diferentes: forma do pacto e publicidade perante terceiros.", "Oponibilidade", "possibilidade de fazer um direito valer contra terceiros"),

    "1658": row("Na comunhão parcial, em regra integram o patrimônio comum os bens adquiridos durante o casamento, ressalvadas as exclusões legais.", "O momento e a causa da aquisição definem comunicação, não apenas o nome no documento.", "Imóvel comprado onerosamente durante o casamento entra na comunhão, salvo exceção provada.", "Devem ser conferidas as exclusões dos artigos seguintes e eventual sub-rogação de bens particulares.", "Comunicação", "ingresso do bem no patrimônio sujeito à partilha do casal"),
    "1659": row("Ficam fora da comunhão parcial bens anteriores, doações e heranças individuais, sub-rogações particulares, certas dívidas, bens pessoais, instrumentos profissionais e rendas enumeradas.", "A lei preserva origens patrimoniais individuais e obrigações sem benefício comum.", "Herança recebida apenas por um cônjuge permanece particular.", "Frutos, aquisição onerosa posterior e benefício ao casal podem receber tratamento diferente; origem dos recursos deve ser provada.", "Sub-rogação", "substituição de um bem por outro conservando sua natureza patrimonial"),
    "1660": row("Entram na comunhão parcial aquisições onerosas durante o casamento, fatos eventuais, liberalidades a ambos, benfeitorias e frutos percebidos ou pendentes.", "A comunhão alcança incrementos econômicos comuns mesmo registrados em nome de apenas um.", "Prêmio recebido durante o casamento integra o patrimônio comum conforme a regra.", "Doação ou herança exclusivamente individual e demais exceções do regime não se confundem com liberalidade ao casal.", "Frutos", "rendimentos ou produtos periódicos gerados por um bem"),
    "1661": row("Bem cuja causa de aquisição é anterior ao casamento não se comunica, ainda que a formalização ocorra depois.", "O fato jurídico que originou o direito pode preservar caráter particular.", "Compra contratada e paga antes do casamento é formalizada posteriormente e permanece particular.", "É preciso provar a causa anterior; mera alegação ou registro posterior não resolve sozinho a natureza do bem.", "Causa aquisitiva", "fato ou negócio que fundamenta a aquisição do bem"),
    "1662": row("Bem móvel é presumido adquirido durante o casamento se não houver prova de aquisição anterior.", "A presunção facilita partilha, mas admite demonstração documental ou outra prova contrária.", "Veículo sem prova de compra anterior é tratado como adquirido na constância do casamento.", "A presunção é relativa e não substitui análise de doação, herança ou sub-rogação.", "Presunção relativa", "conclusão legal que pode ser afastada por prova contrária"),
    "1663": row("Qualquer cônjuge pode administrar patrimônio comum; dívidas vinculam patrimônios conforme proveito, atos gratuitos exigem anuência conjunta e má gestão permite administração exclusiva por decisão judicial.", "A gestão é compartilhada, com responsabilidade proporcional e proteção contra liberalidade ou malversação unilateral.", "Após desvio comprovado, juiz atribui a gestão dos bens comuns a apenas um cônjuge.", "A extensão da dívida ao patrimônio do outro depende do benefício obtido e deve ser demonstrada.", "Malversação", "administração desleal ou prejudicial de patrimônio"),
    "1664": row("Bens comuns respondem por obrigações destinadas aos encargos familiares, à administração e às imposições legais.", "Dívidas funcionais à família ou ao patrimônio comum podem alcançar a massa comum.", "Despesa necessária de conservação da residência comum é paga com patrimônio comunicável.", "Dívida estritamente pessoal sem proveito familiar não entra automaticamente nesta regra.", "Encargo familiar", "obrigação assumida para manutenção e necessidades da família"),
    "1665": row("O proprietário administra e dispõe de seu patrimônio particular, salvo regra diferente no pacto antenupcial.", "Comunhão parcial não retira autonomia sobre bens excluídos da comunhão.", "Cônjuge administra imóvel herdado exclusivamente por ele.", "Outorga conjugal pode continuar necessária para certos atos imobiliários, apesar da propriedade particular.", "Patrimônio particular", "bens que não integram a comunhão do casal"),
    "1666": row("Dívida contraída para administrar e beneficiar bem particular de um cônjuge não obriga os bens comuns.", "O risco econômico acompanha o patrimônio individual favorecido.", "Empréstimo usado apenas para reformar imóvel particular é suportado pelo respectivo patrimônio.", "Se houver benefício comprovado ao casal ou outra causa comum, a solução pode exigir análise adicional.", "Afetação patrimonial", "vinculação de obrigação ao patrimônio que recebeu o benefício"),

    "1667": row("Na comunhão universal, bens e dívidas presentes e futuros são compartilhados, salvo exclusões legais.", "O regime forma massa patrimonial ampla, mas não absolutamente sem exceções.", "Bem adquirido antes do casamento comunica-se se não estiver em categoria excluída.", "Cláusulas de incomunicabilidade, dívidas específicas e bens legalmente pessoais permanecem fora.", "Comunhão universal", "regime que em regra reúne patrimônio anterior e posterior dos cônjuges"),
    "1668": row("Excluem-se da comunhão universal bens com incomunicabilidade, fideicomisso pendente, certas dívidas anteriores, doações antenupciais restritas e bens pessoais indicados por remissão legal.", "A origem e os gravames preservam determinados bens e obrigações fora da massa comum.", "Herança com cláusula válida de incomunicabilidade permanece particular.", "A exclusão do bem não se estende necessariamente aos frutos e depende da redação do gravame e da lei.", "Incomunicabilidade", "restrição que impede ingresso do bem na comunhão conjugal"),
    "1669": row("Frutos percebidos ou vencidos durante o casamento comunicam-se mesmo quando o bem principal é incomunicável.", "O capital pode continuar particular, enquanto sua renda ingressa na comunhão.", "Aluguel vencido durante o casamento de imóvel incomunicável integra a massa comum.", "Deve-se distinguir fruto, produto e valor de alienação do próprio bem excluído.", "Fruto civil", "renda periódica produzida por um bem, como aluguel"),
    "1670": row("Regras de administração da comunhão parcial também se aplicam à comunhão universal.", "O regime amplo aproveita disciplina anterior sobre gestão, dívidas e atos gratuitos.", "Cônjuges administram massa universal conforme as regras comuns de gestão.", "A remissão não elimina as exclusões específicas da comunhão universal.", "Aplicação remissiva", "uso de regras de outro capítulo por determinação legal"),
    "1671": row("Depois de extinta a comunhão e dividido ativo e passivo, cessa responsabilidade de um cônjuge perante credores do outro.", "A partilha concluída separa patrimônios e obrigações conforme a divisão realizada.", "Após divisão patrimonial, credor pessoal de um ex-cônjuge não cobra automaticamente do outro.", "Direitos de credores anteriores, fraude e obrigações próprias ou solidárias continuam sujeitos às regras aplicáveis.", "Passivo", "conjunto de dívidas e obrigações patrimoniais"),

    "1672": row("Na participação final nos aquestos, cada cônjuge mantém patrimônio próprio durante o casamento e, na dissolução, tem direito à metade das aquisições onerosas do casal.", "O regime funciona como separação na gestão e participação no acréscimo patrimonial ao final.", "Durante o casamento cada um administra seus bens; no divórcio apuram aquisições onerosas e partilham o saldo.", "A meação recai sobre aquestos calculados segundo regras próprias, não sobre metade automática de todo patrimônio.", "Participação final", "regime com autonomia durante o casamento e partilha de aquestos na dissolução"),
    "1673": row("Patrimônio próprio abrange bens anteriores e adquiridos durante o casamento; cada cônjuge os administra e pode alienar livremente os móveis.", "A titularidade individual persiste até a apuração final dos aquestos.", "Cônjuge vende automóvel próprio durante o casamento sem transferir sua administração ao outro.", "Imóveis e atos sujeitos à outorga obedecem às regras legais e ao pacto aplicável.", "Patrimônio próprio", "conjunto de bens titularizados individualmente por cada cônjuge"),
    "1674": row("Na dissolução, calculam-se os aquestos excluindo bens anteriores, sub-rogações, sucessões, liberalidades e dívidas ligadas a esses bens; móveis presumem-se adquiridos durante o casamento.", "O cálculo separa acréscimo oneroso comum de patrimônio individual.", "Herança e dívida de sua conservação são retiradas da base de partilha.", "A presunção sobre móveis admite prova contrária e documentos de origem são relevantes.", "Monte dos aquestos", "valor líquido considerado para participação patrimonial ao fim do regime"),
    "1675": row("Doação feita sem autorização necessária é computada nos aquestos; o prejudicado pode reivindicar o bem ou incluir valor equivalente na partilha.", "A regra neutraliza liberalidade unilateral que reduza a futura meação.", "Cônjuge doa ativo relevante sem outorga e o valor é reposto na apuração final.", "A escolha entre reivindicação e recomposição depende do caso, de terceiros e do valor na data legal.", "Recomposição", "reintegração econômica de valor retirado indevidamente da partilha"),
    "1676": row("Valor de bem alienado para prejudicar a meação entra no monte, salvo preferência do lesado ou herdeiros por reivindicá-lo.", "Alienação fraudulenta não reduz a participação econômica do outro cônjuge.", "Bem é vendido para esvaziar a partilha e seu valor é reinserido no cálculo.", "Fraude e detrimento devem ser provados; proteção de terceiro pode influenciar a restituição específica.", "Meação", "parcela patrimonial atribuída ao cônjuge na divisão do regime"),
    "1677": row("Dívida posterior ao casamento obriga apenas quem a assumiu, salvo prova de benefício parcial ou total ao outro.", "Responsabilidade acompanha o devedor, mas o proveito compartilhado pode ampliar seu alcance.", "Empréstimo pessoal sem benefício ao casal fica a cargo do contratante.", "Quem alega benefício comum deve demonstrá-lo e delimitar sua extensão.", "Reversão em benefício", "proveito econômico recebido por pessoa que não contraiu a dívida"),
    "1678": row("Pagamento da dívida de um cônjuge com patrimônio do outro é atualizado e descontado da meação do devedor na dissolução.", "O sistema recompõe o patrimônio de quem suportou obrigação alheia.", "Um cônjuge quita dívida pessoal do outro e recebe ajuste atualizado na partilha.", "É necessário provar origem dos recursos, dívida paga e critério de atualização.", "Imputação", "lançamento de valor a débito ou crédito na apuração patrimonial"),
    "1679": row("Bem obtido pelo trabalho conjunto pertence em quotas iguais aos cônjuges.", "A colaboração comum gera condomínio igualitário, mesmo no regime de participação final.", "Casal desenvolve conjuntamente ativo econômico e cada um possui metade.", "Trabalho conjunto e origem do bem precisam ser demonstrados; pacto ou titularidade de terceiro podem alterar o caso.", "Condomínio", "titularidade simultânea de um bem por mais de uma pessoa"),
    "1680": row("Perante terceiros, móvel presume-se do cônjuge devedor, exceto se for de uso pessoal do outro.", "A presunção facilita responsabilidade patrimonial externa, preservando objetos pessoais identificáveis.", "Credor considera veículo na posse do devedor como dele, salvo prova contrária adequada.", "A presunção protege circulação, mas pode ser afastada e não autoriza constrição de bem pessoal comprovado do outro.", "Presunção dominial", "inferência legal sobre quem é proprietário de determinado bem"),
    "1681": row("Imóvel pertence ao cônjuge indicado no registro; se a titularidade for contestada, ele deve provar aquisição regular.", "Publicidade registral orienta a propriedade, mas impugnação pode exigir demonstração do título e da origem.", "Cônjuge registrado apresenta contrato e pagamento regular diante de contestação.", "O registro tem força jurídica, mas fraude, simulação ou direitos de terceiros podem ser discutidos.", "Titular registral", "pessoa indicada no registro imobiliário como proprietária"),
    "1682": row("Durante o casamento sob esse regime, o direito futuro à meação não pode ser renunciado, cedido ou penhorado.", "A expectativa de participação fica protegida até a apuração na dissolução.", "Cônjuge não pode oferecer a futura meação como garantia a credor.", "A restrição alcança o direito à meação, não necessariamente bens próprios já existentes.", "Incessível", "direito que não pode ser transferido a outra pessoa"),
    "1683": row("Em separação ou divórcio, os aquestos são calculados na data em que terminou a convivência.", "O marco econômico busca impedir que aquisições posteriores à ruptura integrem a partilha.", "Casal separa-se de fato e bens posteriores são analisados a partir dessa data.", "A cessação da convivência deve ser provada; efeitos de separação e divórcio seguem interpretação constitucional atual.", "Marco temporal", "data usada para separar efeitos jurídicos antes e depois de um evento"),
    "1684": row("Quando divisão física é inviável ou inconveniente, atribui-se valor aos bens e repõe-se dinheiro ao não proprietário; se isso falhar, bens suficientes podem ser vendidos judicialmente.", "A partilha busca equivalência econômica sem destruir utilidade dos ativos.", "Empresa indivisível fica com um cônjuge, que compensa financeiramente o outro.", "Venda exige avaliação e autorização judicial, sendo solução subsidiária à reposição em dinheiro.", "Partilha em valor", "divisão econômica mediante compensação em vez de fracionamento físico"),
    "1685": row("Na dissolução por morte, calcula-se a meação do sobrevivente pelas regras do regime e a herança segue a sucessão.", "Meação e herança são operações diferentes: primeiro separa-se o patrimônio conjugal, depois distribui-se o acervo hereditário.", "Falecendo um cônjuge, apuram-se aquestos antes de repartir herança aos sucessores.", "Ser meeiro não torna automaticamente o sobrevivente herdeiro sobre todos os mesmos bens; é preciso aplicar regras sucessórias.", "Acervo hereditário", "patrimônio transmitido pela morte depois de apuradas obrigações e meação"),
    "1686": row("Dívidas individuais acima da meação do devedor não alcançam o outro cônjuge nem seus herdeiros.", "O excesso permanece ligado ao patrimônio do responsável pela obrigação.", "Dívida pessoal supera a quota do devedor e não consome a parcela do outro.", "Obrigação solidária, benefício comum ou garantia própria podem gerar resultado diferente.", "Excesso de dívida", "parte da obrigação que ultrapassa o patrimônio atribuído ao devedor"),

    "1687": row("Na separação convencional, cada cônjuge administra, vende e onera livremente seus próprios bens.", "Não se forma massa comunicável apenas pelo casamento.", "Cônjuge vende imóvel particular sem partilha do preço, observadas regras aplicáveis.", "Separação patrimonial não elimina deveres familiares, dívidas comuns voluntárias ou efeitos de esforço e contratos específicos.", "Separação convencional", "regime escolhido que mantém patrimônios autônomos"),
    "1688": row("Ambos contribuem para despesas do casal proporcionalmente à renda do trabalho e dos bens, salvo regra diferente no pacto.", "Autonomia patrimonial convive com solidariedade na manutenção familiar.", "Quem recebe renda maior assume parcela proporcionalmente superior das despesas, se o pacto não dispuser diferente.", "A contribuição deve respeitar igualdade, possibilidades concretas e dever de assistência.", "Contribuição proporcional", "participação calculada conforme recursos de cada pessoa"),

    "1689": row("Enquanto exercem poder familiar, pai e mãe usufruem e administram bens dos filhos menores.", "A gestão parental visa sustento e interesse do filho, sem transferir propriedade aos pais.", "Pais administram aluguel de imóvel pertencente ao filho menor.", "Usufruto e administração têm exclusões legais e não autorizam apropriação ou disposição ilimitada.", "Usufruto legal", "direito parental de perceber frutos dos bens do filho nos limites da lei"),
    "1690": row("Pais representam filhos abaixo de dezesseis anos e assistem os demais menores; decisões patrimoniais devem ser comuns, com solução judicial para divergência.", "A forma de participação civil muda com a idade e preserva desenvolvimento progressivo da autonomia.", "Adolescente de dezessete anos pratica ato com assistência parental.", "Representação e assistência não eliminam escuta do filho nem regras especiais de capacidade e conflito.", "Representação", "atuação do responsável em nome de quem não pode praticar sozinho o ato"),
    "1691": row("Pais só podem alienar ou onerar imóveis do filho e assumir obrigações além da gestão ordinária com necessidade ou interesse evidente e autorização judicial prévia.", "O patrimônio do menor recebe proteção reforçada contra disposição parental.", "Venda de imóvel do filho é autorizada porque financia tratamento indispensável e vantajoso.", "Ato sem autorização pode ser declarado nulo por filhos, herdeiros ou representante legal.", "Simples administração", "atos rotineiros de conservação e gestão que não comprometem o patrimônio"),
    "1692": row("Conflito entre interesse dos pais e do filho leva à nomeação judicial de curador especial, a pedido do filho ou do Ministério Público.", "Representante independente protege o menor na situação específica de incompatibilidade.", "Pai pretende comprar bem do filho e o juiz nomeia curador para defendê-lo.", "O conflito precisa ser concreto; a curadoria é delimitada ao ato ou processo em que ocorre.", "Curador especial", "representante nomeado para defender incapaz em conflito com seu responsável"),
    "1693": row("Certos bens ficam fora do usufruto e da administração parental: aquisições anteriores a reconhecimento, ganhos profissionais após dezesseis anos, liberalidades restritas e herança quando pais foram excluídos.", "A lei reserva ao filho esferas patrimoniais autônomas ou incompatíveis com gestão dos pais.", "Renda profissional de filho maior de dezesseis anos não é usufruída pelos pais.", "A exclusão deve ser identificada por origem e condição do bem; não extingue outros deveres do poder familiar.", "Exclusão do usufruto", "afastamento legal do direito parental aos frutos do bem"),

    "1694": row("Parentes, cônjuges e companheiros podem pedir alimentos necessários a vida compatível com sua condição e educação; valor considera necessidade e recursos, com redução quando a necessidade decorre de culpa do requerente.", "Alimentos equilibram necessidade de quem pede e possibilidade de quem paga, abrangendo mais que comida.", "Filho sem meios recebe pensão compatível com suas necessidades e renda do genitor.", "Referências à culpa e condição social devem ser aplicadas conforme Constituição, solidariedade familiar e jurisprudência vigente.", "Binômio alimentar", "equilíbrio entre necessidade do credor e possibilidade do devedor"),
    "1695": row("Alimentos são devidos quando o requerente não possui bens nem consegue manter-se pelo trabalho, e o obrigado pode pagar sem comprometer o próprio necessário.", "A obrigação depende simultaneamente de necessidade e capacidade econômica.", "Pessoa impossibilitada de trabalhar demonstra necessidade, enquanto o parente possui renda suficiente.", "O exame é concreto e pode considerar vulnerabilidade, patrimônio, renda e despesas essenciais de ambos.", "Mantença", "recursos indispensáveis à subsistência digna"),
    "1696": row("A obrigação alimentar é recíproca entre pais e filhos e alcança ascendentes, começando pelos parentes de grau mais próximo.", "A responsabilidade acompanha proximidade familiar e pode mudar quando o primeiro obrigado falta ou não pode pagar.", "Na falta dos pais, avós podem ser chamados conforme necessidade e capacidade.", "Responsabilidade dos avós é complementar e subsidiária, não substituição automática da obrigação parental.", "Grau de parentesco", "distância jurídica entre pessoas de uma mesma linha familiar"),
    "1697": row("Sem ascendentes aptos, a obrigação passa aos descendentes na ordem sucessória e, na falta deles, aos irmãos bilaterais ou unilaterais.", "A lei estabelece sequência de parentes potencialmente responsáveis.", "Pessoa sem pais ou filhos busca alimentos de irmão com capacidade financeira.", "Cada classe só é alcançada conforme ausência ou insuficiência das anteriores e prova dos requisitos alimentares.", "Irmão unilateral", "irmão que compartilha apenas um dos genitores"),
    "1698": row("Se o obrigado prioritário não puder suportar tudo, parentes de grau seguinte concorrem; vários devedores contribuem segundo seus recursos e podem integrar o processo.", "A prestação pode ser dividida para completar a necessidade sem impor encargo desproporcional.", "Pai paga parte possível e avós complementam proporcionalmente.", "Não há solidariedade automática: contribuição é calibrada pela capacidade individual e pelo déficit comprovado.", "Obrigação complementar", "dever de completar prestação que o responsável prioritário não consegue cumprir"),
    "1699": row("Mudança financeira de quem paga ou recebe permite pedir exoneração, redução ou aumento dos alimentos.", "A pensão acompanha alteração relevante do equilíbrio entre necessidade e possibilidade.", "Devedor perde renda substancial e pede revisão judicial do valor.", "A modificação depende de decisão ou acordo válido; não se deve reduzir unilateralmente a prestação fixada.", "Revisional de alimentos", "ação para adaptar pensão a circunstâncias supervenientes"),
    "1700": row("A obrigação alimentar transmite-se aos herdeiros do devedor nos limites e forma legal.", "A morte não extingue automaticamente toda responsabilidade, mas a sucessão não cria encargo ilimitado além da herança.", "Espólio responde conforme forças do patrimônio transmitido e disciplina sucessória.", "É preciso distinguir parcelas vencidas, obrigação futura e limites do acervo hereditário.", "Forças da herança", "limite patrimonial representado pelos bens deixados pelo falecido"),
    "1701": row("O devedor pode pagar pensão ou oferecer hospedagem e sustento, preservando educação do menor; o juiz define a forma quando necessário.", "Prestação pode ocorrer em dinheiro ou diretamente, desde que adequada ao alimentando.", "Parente oferece moradia e custeio direto, e o juiz avalia se a forma protege o beneficiário.", "O devedor não escolhe modalidade abusiva para controlar o credor; circunstâncias e dignidade orientam a decisão.", "Prestação in natura", "cumprimento por bens ou serviços em vez de dinheiro"),
    "1702": row("O texto atribui alimentos ao cônjuge considerado inocente e sem recursos na separação litigiosa, conforme critérios gerais.", "A redação pertence ao antigo modelo de culpa na separação e deve ser compatibilizada com a ordem constitucional do divórcio.", "Ex-cônjuge vulnerável pede alimentos e o juiz examina necessidade, possibilidade e contexto atual, não punição moral automática.", "Não se deve apresentar culpa conjugal como requisito contemporâneo absoluto; prevalecem Constituição e entendimento vinculante aplicável.", "Separação litigiosa", "processo contencioso do antigo regime de separação conjugal"),
    "1703": row("Pais separados contribuem para manutenção dos filhos conforme seus recursos.", "O custeio é compartilhado proporcionalmente, independentemente de com quem o filho resida.", "Um genitor paga despesas diretas e outro pensão ajustada às respectivas rendas.", "Guarda compartilhada não elimina alimentos; necessidades do filho e capacidade de cada responsável orientam a divisão.", "Proporcionalidade parental", "repartição do custeio segundo recursos de cada genitor"),
    "1704": row("O texto disciplina alimentos entre separados e diferencia cônjuge não culpado daquele considerado culpado, reservando a este prestação mínima em condições restritas.", "A redação deve ser interpretada à luz da superação constitucional da culpa como eixo da dissolução matrimonial.", "Ex-cônjuge sem autonomia econômica pede prestação, e o caso é decidido por necessidade, possibilidade e solidariedade atual.", "As categorias de culpa do artigo não devem ser aplicadas mecanicamente após a reforma constitucional do divórcio.", "Alimentos transitórios", "prestação temporária para permitir reorganização econômica do beneficiário"),
    "1705": row("Filho nascido fora do casamento pode pedir alimentos ao genitor, e o juiz pode decretar segredo de justiça a pedido.", "A origem da filiação não limita proteção alimentar nem igualdade entre filhos.", "Filho reconhecido ajuíza ação de alimentos e o processo tramita com acesso restrito.", "Sigilo depende da disciplina processual e não reduz direito de defesa ou prova da filiação.", "Segredo de justiça", "restrição de acesso ao processo para proteger intimidade e interesses legais"),
    "1706": row("Alimentos provisórios ou provisionais são fixados judicialmente conforme a legislação processual.", "A tutela rápida assegura subsistência enquanto o processo principal ainda tramita.", "No início da ação, o juiz define prestação temporária com base nos elementos disponíveis.", "Valor inicial pode ser revisto e depende de prova sumária, rito aplicável e posterior contraditório.", "Alimentos provisórios", "prestação temporária fixada antes da decisão final"),
    "1707": row("O credor pode deixar de cobrar, mas não renunciar ao direito a alimentos; o crédito não pode ser cedido, compensado ou penhorado.", "A natureza existencial protege a prestação contra disposição que comprometa subsistência.", "Credor não cobra uma parcela, mas não vende a terceiro seu direito alimentar futuro.", "Distinga direito futuro, parcelas vencidas e acordos permitidos; regras processuais podem tratar créditos acumulados de modo específico.", "Irrenunciabilidade", "impossibilidade de abandonar definitivamente determinado direito protegido"),
    "1708": row("Casamento, união estável ou concubinato do credor encerra o dever alimentar; procedimento indigno contra o devedor também pode cessar o direito.", "Nova estrutura afetiva pode alterar fundamento da solidariedade anterior, e conduta grave pode repercutir na prestação.", "Credor constitui nova união e o devedor pede reconhecimento da cessação.", "Cessação deve ser juridicamente apurada; namoro não equivale automaticamente a união estável e indignidade exige prova.", "Cessação", "término do dever de prestar a obrigação"),
    "1709": row("Novo casamento de quem paga não extingue alimentos fixados no divórcio.", "A formação de outra família não apaga obrigação anterior estabelecida judicialmente.", "Devedor casa novamente e continua pagando pensão ao ex-cônjuge nos termos da sentença.", "Mudança econômica pode justificar revisão, mas não interrupção unilateral pelo novo casamento.", "Exoneração", "decisão que encerra obrigação alimentar anteriormente existente"),
    "1710": row("Prestações alimentícias devem ser corrigidas por índice oficial regularmente definido.", "Atualização preserva poder de compra do valor ao longo do tempo.", "Pensão é reajustada segundo índice previsto na decisão ou norma aplicável.", "Correção monetária não se confunde com aumento por mudança de necessidade, que exige revisão própria.", "Atualização monetária", "recomposição do valor nominal diante da inflação"),

    "1711": row("Cônjuges ou entidade familiar podem instituir bem de família voluntário por escritura ou testamento até um terço do patrimônio líquido, sem afastar a proteção residencial da lei especial; terceiro também pode instituí-lo com aceitação.", "O instituto separa patrimônio para moradia e sustento familiar mediante forma e limite próprios.", "Família registra imóvel residencial como bem de família dentro do limite patrimonial.", "O bem voluntário do Código não se confunde com a impenhorabilidade legal automática da residência prevista em lei especial.", "Bem de família voluntário", "patrimônio formalmente destinado à proteção e manutenção da família"),
    "1712": row("O bem de família pode compreender residência urbana ou rural, acessórios e valores mobiliários cuja renda conserve o imóvel e sustente a família.", "A proteção reúne moradia e, dentro dos requisitos, ativos financeiros vinculados à sua manutenção.", "Instituição inclui casa e títulos cuja renda paga conservação e despesas familiares.", "Os valores precisam estar afetados à finalidade familiar e observar limites e individualização legais.", "Pertenças", "bens destinados de modo duradouro ao uso ou serviço de outro bem"),
    "1713": row("Valores mobiliários vinculados não podem superar o valor do imóvel, devem ser individualizados e registrados quando nominativos, podendo ser administrados por instituição financeira.", "A lei controla quantidade, identificação e gestão dos ativos acessórios.", "Escritura identifica títulos e confia sua administração a banco com regras de repasse da renda.", "Administrador responde conforme o contrato de depósito e os ativos não podem ser genericamente indicados.", "Título nominativo", "valor mobiliário registrado em nome de titular identificado"),
    "1714": row("O bem de família voluntário nasce com o registro do título no Registro de Imóveis.", "Escritura ou testamento, isoladamente, não conclui sua constituição perante terceiros.", "Família lavra escritura e efetiva a proteção ao registrá-la na matrícula.", "O registro deve observar procedimento, publicidade e requisitos patrimoniais do instituto.", "Registro constitutivo", "registro indispensável para o próprio nascimento do direito"),
    "1715": row("O bem de família fica protegido de dívidas posteriores, exceto tributos do imóvel e despesas condominiais; eventual saldo de execução recebe destinação familiar sob controle judicial.", "A proteção não cobre obrigações diretamente ligadas ao próprio prédio e não é escudo absoluto.", "Condomínio executa dívida da unidade protegida, e o juiz destina eventual saldo conforme a lei.", "Dívidas anteriores, fraude e exceções da legislação especial exigem análise; o artigo trata do bem voluntário.", "Impenhorabilidade", "proteção que impede constrição judicial em determinadas dívidas"),
    "1716": row("A proteção dura enquanto viver um dos cônjuges ou, na ausência deles, até a maioridade dos filhos.", "O período acompanha a existência do núcleo familiar protegido pela instituição.", "Após morte de ambos, a isenção persiste enquanto houver filho menor.", "Curatela e hipóteses posteriores do regime podem exigir leitura sistemática, não encerramento automático fora do texto isolado.", "Duração da isenção", "período em que a proteção contra execução permanece ativa"),
    "1717": row("Imóvel e valores do bem de família não podem mudar de finalidade nem ser alienados sem consentimento dos interessados e representantes, com participação do Ministério Público.", "A afetação familiar limita disposição unilateral do patrimônio protegido.", "Venda é pretendida e passa pelo consentimento e controle exigidos.", "Consentimento não dispensa registro, proteção de incapazes e demais autorizações aplicáveis.", "Afetação", "vinculação jurídica de patrimônio a uma finalidade específica"),
    "1718": row("Liquidação da instituição financeira administradora não alcança os valores do bem de família, que devem ser transferidos por ordem judicial.", "Os ativos afetados ficam separados do patrimônio da administradora.", "Banco entra em liquidação e o juiz transfere os títulos familiares para outra instituição.", "A segregação depende da identificação regular dos ativos e segue regras de restituição na falência.", "Patrimônio segregado", "bens separados do patrimônio próprio de quem apenas os administra"),
    "1719": row("Impossibilidade comprovada de manter o bem permite ao juiz extingui-lo ou substituir seus ativos, após ouvir interessados, instituidor e Ministério Público.", "A finalidade familiar pode ser adaptada judicialmente quando a estrutura original se torna inviável.", "Imóvel fica economicamente insustentável e é substituído por residência adequada mediante autorização.", "Extinção ou sub-rogação não decorre de conveniência simples; exige prova, participação dos legitimados e decisão.", "Sub-rogação real", "substituição de um bem por outro que assume sua mesma destinação jurídica"),
    "1720": row("Salvo regra diferente no ato, ambos os cônjuges administram o bem de família; o juiz resolve divergências e, após morte de ambos, a gestão passa ao filho mais velho maior ou ao tutor.", "A administração é conjunta e possui solução legal de continuidade.", "Cônjuges discordam sobre aplicação da renda e submetem a questão ao juiz.", "A regra deve ser aplicada com igualdade entre responsáveis e proteção de incapazes, sem transformar primogenitura em privilégio patrimonial.", "Administração conjunta", "gestão que exige participação coordenada de mais de um responsável"),
}

